function hospitalDetails(id){const h=hospitals.find(h=>h.id===id);if(!h)return;modal('医院详情',`<section class="visit-header">${hospitalPhoto(h)}<div><h2>${esc(h.name)}</h2><p>${esc(h.branch)} · ${esc(h.area)}</p><p>★ ${h.rating} · 距你 ${h.distance} km</p></div></section>${tags(h.tags)}<div class="detail"><b>接诊信息</b><p>营业时间：${esc(h.hours)}</p><p>参考费用：${esc(h.price)}</p></div><div class="detail"><b>医院特色</b><p>${esc(h.feature)}</p></div><div class="detail"><b>就诊准备</b><p>带好报告与处方，整理近期症状。</p></div><p class="microcopy">演示资料 · 接诊与费用以医院确认为准</p><div class="hospital-detail-actions"><button class="outline-btn" data-detail-toggle="${id}">${state.compare.includes(id)?'移出对比':'加入对比'}</button><button class="cta" data-detail-appointment="${id}">预约这家医院</button></div>`);}
document.addEventListener('click',e=>{const entry=e.target.closest('[data-hospital-detail]');if(entry){hospitalDetails(+entry.dataset.hospitalDetail);return;}const b=e.target.closest('button');if(!b)return;if(b.dataset.detailToggle){const id=+b.dataset.detailToggle;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<2)state.compare.push(id);else{toast('最多选择两家医院进行对比');return;}b.textContent=state.compare.includes(id)?'移出对比':'加入对比';const top=scroll.scrollTop;render();scroll.scrollTop=top;}if(b.dataset.detailAppointment){const h=hospitals.find(h=>h.id===+b.dataset.detailAppointment);modal('预约就诊',`<form id="booking-form" class="entry-form"><div class="detail"><b>${esc(h.name)} · ${esc(h.branch)}</b><p>${esc(currentPet().name)}</p></div><label>意向日期<input name="date" type="date" required></label><label>意向时段<select name="slot"><option>上午 10:00</option><option>下午 14:00</option><option>晚上 19:00</option></select></label><p class="microcopy">演示预约，不占用真实医院号源，时段须由医院确认。</p><button class="cta" type="submit">确认演示预约</button></form>`);}});
document.addEventListener('keydown',e=>{const el=e.target.closest('[data-hospital-detail]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();hospitalDetails(+el.dataset.hospitalDetail);}});

/* Shallow navigation and small, accessible motion. */
function syncCoreNavigation(){nav.style.display='flex';nav.inert=false;const section=subpageOpen?(/医院|预约|就医/.test($('#sheet-title').textContent)?'care':/用药/.test($('#sheet-title').textContent)?'medicine':null):null;const active=section||({home:'home',symptom:'care',hospitals:'care',compare:'care',visit:'archive',archive:'archive',medication:'medicine',profile:'pet',petdetail:'pet'})[state.route];nav.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.nav===active);if(b.dataset.nav===active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function enterMotion(el){if(!el||matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.classList.contains('reduce-motion'))return;el.animate([{opacity:.5,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,easing:'ease-out'});}
