function showWelcome(){if($('#welcome-screen'))return;const screen=document.createElement('section');screen.id='welcome-screen';screen.setAttribute('aria-label','欢迎使用 PawCare');screen.innerHTML=`<div class="welcome-visual" role="img" aria-label="女主人与猫依偎着看窗外风景"></div><div class="welcome-panel"><div class="welcome-brand"><div class="welcome-wordmark">${I('paw')}<h1>PawCare</h1></div><p>陪你记录每一次照护</p></div><div class="welcome-actions"><button class="cta" data-demo-enter><span>进入体验</span><span class="welcome-enter-arrow" aria-hidden="true">${I('arrow')}</span></button><small>免注册体验 · 演示数据</small></div></div>`;$('.phone').append(screen);for(const el of $('.phone').children)if(el!==screen&& !el.classList.contains('status')&&!el.classList.contains('home-indicator'))el.inert=true;}
