/* Data-led visual variety, using only existing pet and medication information. */
function careRing(done,total,label){const n=Math.max(0,Math.min(done,total)),pct=total?n/total:0;return `<div class="care-ring" role="img" aria-label="${esc(label)}：${n}/${total}"><svg viewBox="0 0 64 64" aria-hidden="true"><circle class="ring-track" cx="32" cy="32" r="26"/><circle class="ring-value" cx="32" cy="32" r="26" stroke-dasharray="${pct*163.36} 163.36"/></svg><strong>${n}<small>/${total}</small></strong></div>`;}
function companionSketch(){return `<div class="companion-sketch" aria-hidden="true"><svg viewBox="0 0 120 84"><ellipse cx="60" cy="73" rx="43" ry="6" fill="#F6EDF0" stroke="none"/><path d="M33 56V26l16 9q12-5 24 0l15-9v30q0 17-27 17T33 56Z"/><path d="m41 33 7 7m32-7-7 7M47 51q4 4 8 0m13 0q4 4 8 0m-18 5 4 3 4-3m-4 3v5m-17-5-13-2m13 7-12 2m44-7 13-2m-13 7 12 2"/><path class="sketch-accent" d="M98 17c-6-8-15 1 0 11 15-10 6-19 0-11Z"/></svg></div>`;}
function enrichCareVisuals(){
 if(state.route==='home'){
 const heading=scroll.querySelector('.reminders .section-heading');
 const total=state.meds.reduce((n,m)=>n+timesFor(m).length,0),done=state.meds.reduce((n,m)=>n+timesFor(m).filter(t=>logFor(m)[t]).length,0);
 if(heading&&total)heading.insertAdjacentHTML('afterend',`<div class="today-progress">${careRing(done,total,'今日用药已完成')}<div><b>${total-done?`还有 ${total-done} 次用药`:'今日用药已完成'}</b><span>今日用药</span></div><span class="progress-status">${done===total?'已完成':'进行中'}</span></div>`);
 }
 if(state.route==='medication'&&state.medTab==='当前用药'){
 scroll.querySelectorAll('.med-card').forEach((card,i)=>{const m=state.meds[i];if(!m)return;const copy=card.querySelector('.progress-copy');if(copy){copy.outerHTML=`<div class="course-progress">${careRing(Math.min(+m.day,+m.days),+m.days,'疗程进度')}<div><b>疗程进度</b><p>已用 ${m.day} 天 · 共 ${m.days} 天</p></div></div>`;card.querySelector('.progress-track')?.remove();}});
 const review=scroll.querySelector('.review-card');if(review&&/^\d{4}-\d{2}-\d{2}$/.test(state.review||'')){const parts=state.review.split('-');review.firstElementChild?.remove();review.insertAdjacentHTML('afterbegin',`<div class="review-date" aria-label="${esc(state.review)}"><span>${Number(parts[1])}月</span><b>${parts[2]}</b></div>`);}
 }
 if(state.route==='archive'&&state.archiveTab==='时间轴')scroll.querySelectorAll('.timeline-date>span').forEach(el=>{const icon=el.textContent==='疫苗'?'shield':el.textContent==='体检'?'clipboard':'stethoscope';el.insertAdjacentHTML('afterbegin',I(icon));});
 scroll.querySelectorAll('.empty-pet-state').forEach(el=>{if(!el.querySelector('.companion-sketch')){el.querySelector(':scope>svg,:scope>span[data-icon]')?.remove();el.insertAdjacentHTML('afterbegin',companionSketch());}});
}
const renderBeforeCareVisuals=render;render=function(){renderBeforeCareVisuals();enrichCareVisuals();};
