/* Photo-led, centered pet carousel in My Pets. */
const renderBeforeProfilePhotoCards=render;
render=function(){renderBeforeProfilePhotoCards();if(state.route!=='profile')return;const index=petStore.pets.findIndex(p=>p.id===currentPet().id);scroll.querySelectorAll('.pet-slide').forEach(card=>{card.classList.add('pet-photo-slide');const p=petStore.pets.find(p=>p.id===card.dataset.petId);if(!p)return;card.querySelector('.select-pet')?.remove();const main=card.querySelector('.pet-card-main');const info=main?.querySelector('div:not(.avatar)');if(info&&!info.querySelector('.pet-photo-status'))info.insertAdjacentHTML('beforeend',`<span class="pet-photo-status">${p.id===currentPet().id?'当前照护':'点击查看档案'}</span>`);});const hint=scroll.querySelector('.pet-switch-hint');if(hint)hint.outerHTML=`<div class="pet-carousel-controls"><button aria-label="上一只宠物" ${index>0?`data-select-pet="${petStore.pets[index-1].id}"`:'disabled'}>${I('back')}</button><span>${petStore.pets.length>1?'左右滑动切换宠物':'我的宠物'} <b>${index+1} / ${petStore.pets.length}</b></span><button aria-label="下一只宠物" ${index<petStore.pets.length-1?`data-select-pet="${petStore.pets[index+1].id}"`:'disabled'}>${I('chevron')}</button></div>`;};
/* Compact voice input: waveform, one action, and structured results. */
const renderBeforeCompactVoice=render;
render=function(){renderBeforeCompactVoice();if(state.route!=='symptom')return;const card=scroll.querySelector('.symptom-voice-card');if(!card)return;const labels=[...new Set([...state.symptoms,state.duration,state.appetite&&'食欲'+state.appetite,state.energy&&'精神'+state.energy].filter(Boolean))].slice(0,4);card.classList.add('compact-voice');card.innerHTML=`<div class="compact-voice-copy"><h2>语音描述症状</h2><p class="symptom-voice-caption">说说最近的变化，我来帮你整理</p><div class="voice-wave" aria-hidden="true">${[5,10,16,8,20,12,7,15,10,5,11,6].map((h,i)=>`<i style="--wave-height:${h}px;--wave-delay:${i*8}ms"></i>`).join('')}</div></div><button class="voice-mic-action" data-action="voice" aria-label="体验语音描述症状">${I('mic')}</button><div class="voice-summary-tags"><span class="voice-summary-label">${labels.length?'已识别 / 已填写':'待识别'}</span><div>${labels.map(label=>`<span>${esc(label)}</span>`).join('')}</div></div>`;};
window.addEventListener('click',e=>{const b=e.target.closest('.compact-voice:not(.visit-voice-card) .voice-mic-action');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.disabled)return;b.disabled=true;const card=b.closest('.compact-voice');card.classList.add('voice-activating');setTimeout(()=>{b.disabled=false;card.classList.remove('voice-activating');if(state.route==='symptom'&&!sheet.open)voice();},200);},true);
/* Visit details use pet-first identity, a hospital selector and compact voice input. */
function visitHospitalRecord(){return state.extraRecords.find(r=>r.voiceDetails&&r.recordId===activeVoiceVisit);}
function selectedVisitHospital(){return visitHospitalRecord()?.hospital||currentPet().visitHospital||'瑞鹏宠物医院 · 万象城分院';}
const renderBeforeVisitRefresh=render;
render=function(){renderBeforeVisitRefresh();if(state.route!=='visit')return;const header=scroll.querySelector('.visit-header');if(!header)return;const p=currentPet();const date=visitHospitalRecord()?.date||'2025.08.14';header.remove();const mini=scroll.querySelector('.pet-mini');if(mini)mini.outerHTML=`<section class="symptom-pet-card photo-led"><div class="symptom-pet-copy"><button class="symptom-pet-switch" data-route="petdetail"><b>${esc(p.name)}</b>${I('chevron')}</button><p>${esc(p.breed)} · ${petAge(p)} · ${esc(p.sex)}</p><span class="symptom-pet-status">${I('record')}就诊记录</span></div>${avatar(p)}</section><button class="visit-hospital-select" data-visit-hospital-picker><span>${I('stethoscope')}</span><div><small>选择医院</small><b>${esc(selectedVisitHospital())}</b><p>${esc(date)} · ${esc(visitHospitalRecord()?.doctor||(p.visitHospital?'医生待补充':'李医生 · 猫科'))}</p></div>${I('chevron')}</button>`;
const entry=scroll.querySelector('[data-visit-voice]');if(entry)entry.outerHTML=`<section class="symptom-voice-card compact-voice visit-voice-card"><div class="compact-voice-copy"><h2>语音整理诊断记录</h2><p class="symptom-voice-caption">说说医生的医嘱，我来帮你整理</p><div class="voice-wave" aria-hidden="true">${[5,10,16,8,20,12,7,15,10,5,11,6].map(h=>`<i style="--wave-height:${h}px"></i>`).join('')}</div></div><button class="voice-mic-action" data-visit-voice aria-label="体验语音整理诊断记录">${I('mic')}</button><div class="voice-summary-tags"><span class="voice-summary-label">${visitHospitalRecord()?'已确认':'整理内容'}</span><div><span>就诊原因</span><span>医生诊断</span><span>治疗方案</span></div></div></section>`;
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-visit-hospital-picker'))modal('选择就诊医院',`<div class="visit-hospital-options">${hospitals.map(h=>`<button data-visit-hospital-id="${h.id}" aria-pressed="${selectedVisitHospital().includes(h.name)}">${hospitalPhoto(h)}<div><b>${esc(h.name)}</b><p>${esc(h.branch)} · ${esc(h.area)}</p></div>${I(selectedVisitHospital().includes(h.name)?'check':'chevron')}</button>`).join('')}</div>`);if(b.dataset.visitHospitalId){const h=hospitals.find(h=>h.id===+b.dataset.visitHospitalId);if(!h)return;const name=h.name+' · '+h.branch,r=visitHospitalRecord();if(r){r.hospital=name;r.voiceDetails.hospital=name;r.doctor='医生待补充';}else currentPet().visitHospital=name;savePets();sheet.close();render();}});
const draftBeforeHospitalSelection=visitVoiceDraft;visitVoiceDraft=function(){draftBeforeHospitalSelection();const input=sheet.querySelector('[name="hospital"]');if(input)input.value=selectedVisitHospital();};

